import {RunEngine,ZONES,POWERUPS} from './engine.js';
import {createWorld} from './world.js';
import {GameAudio} from './audio.js';
import {LAUGH_DURATION,laughPose} from './motion.js';
const $=id=>document.getElementById(id),engine=new RunEngine();let world,best=0,last=0,clock=0,toastUntil=0,audioOn=true,audioContext,helpReturn='menu',previousMode='',holdJump=false,holdTime=0;
try{audioOn=localStorage.getItem('naiwa-audio')!=='off';best=Math.max(0,Number(localStorage.getItem('naiwa-best'))||0)}catch{}
$('mapStart').innerHTML=ZONES.map((name,i)=>`<option value="${i}">${String(i+1).padStart(2,'0')} · ${name}</option>`).join('');
$('bestIntro').textContent=best+' m';engine.takeEvents();
const audio=new GameAudio(audioOn,text=>notify(text));let laughPending=false;
function sound(freq=600,duration=.1,type='sine'){audio.tone(freq,duration,type);}
function updateSoundButton(){$('sound').textContent='声音 '+(audioOn?'开':'关');$('sound').setAttribute('aria-pressed',String(audioOn));}
updateSoundButton();
function selectForm(type=''){engine.previewForm=type;$('viewerTitle').textContent=(type?POWERUPS[type].name:'奶蛙')+'，笑一个。';document.querySelectorAll('[data-form]').forEach(b=>b.classList.toggle('selected',b.dataset.form===type));}
async function playLaugh(){if(!world||laughPending)return;audio.stopLaugh();engine.mode='viewer';engine.laughTime=-1;showMode();laughPending=true;$('laughBtn').disabled=true;$('laughBtn').textContent='正在准备笑声…';try{await audio.laugh('studio');}catch(e){notify('笑声音轨未能播放，请刷新后重试');}finally{laughPending=false;$('laughBtn').disabled=false;}}
document.querySelectorAll('[data-form]').forEach(b=>b.onclick=()=>{audio.stopLaugh();engine.laughTime=-1;selectForm(b.dataset.form);});
$('laughBtn').onclick=playLaugh;$('introLaugh').onclick=()=>{selectForm();playLaugh();};$('stopLaugh').onclick=()=>{audio.stopLaugh();engine.laughTime=-1;};
function notify(text){if(!text)return;$('toast').textContent=text;$('toast').style.opacity=1;toastUntil=clock+2.8}
function showMode(){const m=engine.mode;if(m===previousMode)return;previousMode=m;if(m==='menu')selectForm();const frozen=['paused','upgrade','help','over'].includes(m);if(frozen)audio.suspend();else audio.resume();if(m==='menu')audio.stopLaugh();document.body.dataset.state=m;for(const [id,state]of [['intro','menu'],['viewer','viewer'],['pauseScreen','paused'],['upgrade','upgrade'],['end','over'],['help','help']])$(id).classList.toggle('hidden',m!==state);$('pause').disabled=!['running','paused'].includes(m);$('pause').textContent=m==='paused'?'▶':'Ⅱ';if(m==='upgrade'){$('cards').replaceChildren();for(const [i,u]of engine.choices.entries()){const b=document.createElement('button');b.className='card';b.innerHTML=`<i>${u.icon}</i><b>${u.name}</b><span>${u.desc}</span><small>选择能力 · ${i+1}</small>`;b.onclick=()=>{engine.chooseUpgrade(u.id);showMode()};$('cards').append(b)}}if(m==='over'){const old=best;best=Math.max(best,Math.floor(engine.distance));try{localStorage.setItem('naiwa-best',String(best))}catch{}$('finalDistance').textContent=Math.floor(engine.distance);$('finalCoins').textContent=engine.coins;$('finalRings').textContent=engine.rings;$('finalBest').textContent=best;$('bestIntro').textContent=best+' m';$('endTag').textContent=best>old?'新纪录！奶蛙今天超越了自己':'今天也跑得很努力了';$('reason').textContent=engine.reason;$('challenges').innerHTML=[[engine.distance>=300,'跑过 300 米'],[engine.rings>=3,'穿过 3 个圆环'],[engine.roofRuns>0,'登上一次车顶']].map(([ok,t])=>`<span class="${ok?'done':''}">${ok?'✓':'○'} ${t}</span>`).join('')}}
function start(){if(!world)return;audio.stopLaugh();audio.unlock().catch(()=>notify('点击右上角声音按钮重试'));engine.reset(Number($('mapStart').value));engine.laughTime=-1;holdJump=false;showMode();sound(420)}
$('start').onclick=$('again').onclick=$('restartPause').onclick=start;$('home').onclick=()=>{engine.reset();engine.mode='menu';showMode()};$('pause').onclick=$('resume').onclick=()=>{engine.pause();showMode()};$('modelBtn').onclick=$('inspect').onclick=()=>{if(engine.mode==='menu'){engine.mode='viewer';showMode()}};$('backViewer').onclick=()=>{audio.stopLaugh();engine.mode='menu';engine.laughTime=-1;showMode()};$('helpBtn').onclick=()=>{if(engine.mode==='help')return;helpReturn=engine.mode;engine.mode='help';showMode()};$('closeHelp').onclick=()=>{engine.mode=helpReturn;showMode()};$('sound').onclick=()=>{audioOn=!audioOn;audio.setEnabled(audioOn);try{localStorage.setItem('naiwa-audio',audioOn?'on':'off')}catch{}updateSoundButton();audio.unlock().then(()=>{sound();if(['paused','upgrade','help','over'].includes(engine.mode))audio.suspend();}).catch(()=>notify('声音未能启动，请刷新后重试'));};

function input(action){engine.input(action)}
document.querySelectorAll('[data-action]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();input(b.dataset.action);if(b.dataset.action==='jump'){holdJump=true;holdTime=0}})});addEventListener('pointerup',()=>holdJump=false);addEventListener('pointercancel',()=>holdJump=false);
let touchStart=null;const canvas=$('game');canvas.addEventListener('pointerdown',e=>{if(engine.mode!=='running')return;touchStart={x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointerup',e=>{if(!touchStart)return;const dx=e.clientX-touchStart.x,dy=e.clientY-touchStart.y;touchStart=null;if(Math.max(Math.abs(dx),Math.abs(dy))<18)input('jump');else if(Math.abs(dx)>Math.abs(dy))input(dx>0?'right':'left');else input(dy>0?'slide':'jump')});canvas.addEventListener('pointercancel',()=>touchStart=null);
addEventListener('keydown',e=>{const map={ArrowLeft:'left',a:'left',ArrowRight:'right',d:'right',ArrowUp:'jump',' ':'jump',w:'jump',ArrowDown:'slide',s:'slide',g:'glide',G:'glide',Shift:'dash'};if(map[e.key]||['p','P','Escape','1','2','3'].includes(e.key)){e.preventDefault();if(e.repeat)return;if(engine.mode==='upgrade'&&['1','2','3'].includes(e.key)){const u=engine.choices[Number(e.key)-1];if(u)engine.chooseUpgrade(u.id);return}if(['p','P','Escape'].includes(e.key)){engine.pause();showMode();return}if(e.key===' '&&['menu','over'].includes(engine.mode)){start();return}input(map[e.key]);if(e.key===' '){holdJump=true;holdTime=0}}});addEventListener('keyup',e=>{if(e.key===' ')holdJump=false});document.addEventListener('visibilitychange',()=>{if(document.hidden){audio.suspend();if(engine.mode==='running'){engine.pause();showMode()}}else if(['menu','viewer','running'].includes(engine.mode))audio.resume();holdJump=false});
function hud(){$('distance').innerHTML=String(Math.floor(engine.distance)).padStart(4,'0')+'<small>m</small>';$('hearts').textContent='♥ '.repeat(engine.lives)+'♡ '.repeat(3-engine.lives);$('coins').textContent='✦ '+engine.coins;$('combo').textContent=engine.combo>2?engine.combo+' 连收 · '+engine.rings+' 圆环':'开启新的一跑';$('route').textContent=String(engine.zone+1).padStart(2,'0')+' / '+ZONES[engine.zone];$('speed').textContent=Math.round(engine.speed*3.6)+' km/h';$('speedNote').textContent=engine.naigema>0?'奶格玛 · 自动冲刺':engine.fever>0?'大笑 · 双倍冲刺':'速度持续提升';const active=Object.entries(POWERUPS).filter(([id])=>engine[id]>0);$('powerTimers').innerHTML=active.map(([id,p])=>`<div class="power-timer ${id}"><span>${p.name}</span><b>${p.charges?'抵挡 1 次':engine[id].toFixed(1)+'s'}</b><i style="width:${p.charges?100:engine[id]/p.duration*100}%"></i></div>`).join('');const energy=engine.fever>0?engine.fever/6*100:engine.energy;$('energyFill').style.width=energy+'%';$('energyNumber').textContent=engine.fever>0?Math.ceil(engine.fever)+'s':Math.floor(energy)+'%';$('energyLabel').textContent=engine.fever>0?'☺ 哈哈哈哈！无敌冲刺':'☺ 大笑能量';$('buff').textContent=engine.niulai>0?'牛来骑乘 · 抵挡一次伤害后离开':engine.magnet>0?'∪ 磁铁剩余 '+Math.ceil(engine.magnet)+' 秒':engine.upgrades.has('magnet')?'∪ 永久磁场已生效':'收集金币与完美闪避来蓄力';$('dashText').textContent=engine.dashCooldown>0?Math.ceil(engine.dashCooldown)+'s':'冲刺';$('dashButton').disabled=engine.dashCooldown>0;$('glideButton').classList.toggle('active',engine.gliding);$('airmeter').classList.toggle('hidden',engine.y<.3);$('airFill').style.width=(engine.glideFuel/(engine.upgrades.has('glide')?4.6:2.6)*100)+'%';$('milestoneText').textContent=Math.max(0,Math.ceil(engine.nextUpgrade-engine.distance))+' m';$('milestoneFill').style.width=Math.min(100,(1-(engine.nextUpgrade-engine.distance)/(engine.nextUpgrade===1250?1250:1500))*100)+'%';$('eventBanner').classList.toggle('hidden',!engine.event);$('eventBanner').textContent=engine.event==='gold'?'✦ 金币雨 · 收集翻倍 '+Math.ceil(engine.eventTime)+'s':'☂ 雨中慢跑 · '+Math.ceil(engine.eventTime)+'s'}
function frame(now){const dt=Math.min((now-last)/1000||.016,.05);last=now;clock+=dt;if(holdJump&&engine.mode==='running'){holdTime+=dt;if(holdTime>.32&&engine.y>.4&&!engine.gliding){engine.input('glide');holdJump=false}}engine.tick(dt);for(const event of engine.takeEvents()){if(['star','ring','smash'].includes(event.type)){world.burst(event.data,engine);sound(event.type==='star'?650+(engine.coins%5)*90:900,.06)}else if(event.type==='transform'){sound(980,.25,'triangle');}else if(event.type==='jump')sound(400,.13);else if(event.type==='cowBreak')sound(240,.22,'triangle');else if(event.type==='hit')sound(100,.2,'triangle');else if(event.type==='fever'){audio.laugh('run').catch(()=>notify('笑声未能播放'));};if(event.type!=='star'&&event.type!=='smash'&&event.type!=='avoid')notify(event.text)}showMode();if(clock>toastUntil)$('toast').style.opacity=0;hud();if(audio.kind==='run'&&engine.fever<=0)audio.stopLaugh();engine.laughTime=audio.time>=0?audio.time:engine.fever>0?6-engine.fever:-1;audio.update(engine);if(engine.mode==='viewer'&&!laughPending){const t=audio.time;$('laughBtn').textContent=t>=0?'再笑一次 ↻':'捧腹大笑 ▶';$('laughProgress').style.width=(t>=0?Math.min(100,t/LAUGH_DURATION*100):0)+'%';$('laughStage').textContent=t>=0?laughPose(t).stage+' · '+t.toFixed(1)+' / 14.1s':'点击播放完整动作与笑声';$('stopLaugh').hidden=t<0;}world.render(engine,clock,dt);requestAnimationFrame(frame)}
try{world=createWorld(canvas);$('loading').classList.add('hidden');$('start').disabled=false;$('start').innerHTML='开跑，奶蛙！<span>↗</span>';showMode();requestAnimationFrame(frame)}catch(e){$('loading').classList.add('hidden');$('error').classList.remove('hidden');$('errorText').textContent='当前浏览器无法启动 WebGL 2。请尝试使用最新版 Chrome / Edge，或开启硬件加速。';document.querySelector('.footerstatus').textContent='当前浏览器无法显示 3D';console.error('3D initialization failed',e)}
